import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# -----------------------------
# Custom CUDA source for fused linear + tanh
# -----------------------------
linear_tanh_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Kernel for linear + tanh: out = tanh( input @ weight^T + bias )
__global__ void linear_tanh_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_features,
    const int out_features)
{
    int row = blockIdx.x;
    int col = threadIdx.x;

    if (row < batch_size && col < out_features) {
        float val = bias[col];
        // Matrix multiply for one element
        for (int i = 0; i < in_features; i++) {
            val += input[row * in_features + i] * weight[col * in_features + i];
        }
        // Apply tanh
        val = tanhf(val);
        output[row * out_features + col] = val;
    }
}

torch::Tensor linear_tanh_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias)
{
    // input: (batch_size, in_features)
    // weight: (out_features, in_features)
    // bias: (out_features)
    const auto batch_size = input.size(0);
    const auto in_features = input.size(1);
    const auto out_features = weight.size(0);

    auto output = torch::empty({batch_size, out_features}, input.options());

    const dim3 grid(batch_size);
    const dim3 block(out_features);

    linear_tanh_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return output;
}
""".strip()

linear_tanh_cpp_source = (
