fused_linear_tanh_ext = load_inline(
    name="fused_linear_tanh_ext",
    cpp_sources=linear_tanh_cpp_source,
    cuda_sources=linear_tanh_source,
    functions=["linear_tanh_cuda"],
    verbose=False,
)

linear_ext = load_inline(
    name="linear_ext",
    cpp_sources=linear_cpp_source,
    cuda_sources=linear_source,
    functions=["linear_cuda"],
    verbose=False,
)

# -----------------------------
# Optimized Model
# -----------------------------
class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size

        # Store an internal hidden state
        self.hidden = torch.randn((8, hidden_size))  # same shape as original

        # We use nn.Linear to hold parameters but call custom CUDA kernels for forward
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)
        self.h2o = nn.Linear(hidden_size, output_size)
        self.tanh = nn.Tanh()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Move hidden to same device as x
        self.hidden = self.hidden.to(x.device)

        # Concatenate input and hidden
        combined = torch.cat((x, self.hidden), dim=1)

        # Compute new hidden via custom linear + tanh
        new_hidden = fused_linear_tanh_ext.linear_tanh_cuda(
            combined,
            self.i2h.weight,
            self.i2h.bias
        )

        # Optional: compute an output; the original code doesn't return it,
        # but we'll still compute it for completeness
        _ = linear_ext.linear_cuda(new_hidden, self.h2o.weight, self.h2o.bias)

        # Update self.hidden
        self.hidden = new_hidden
        return self.hidden

